-- Minecraft sound events: a sound event has several variants with their own
-- volume, pitch and weight (sounds.json). The variants are listed in
-- events.lua, generated by tools/mc_deepdark_assets.py.
mcl_mcsounds = {}

local modpath = core.get_modpath(core.get_current_modname())
local events = dofile(modpath .. "/events.lua")
mcl_mcsounds.events = events

local random = math.random

local function pick(variants)
	local total = 0
	for _, v in ipairs(variants) do
		total = total + (v.weight or 1)
	end
	local r = random() * total
	for _, v in ipairs(variants) do
		r = r - (v.weight or 1)
		if r < 0 then
			return v
		end
	end
	return variants[#variants]
end

-- Adds sound events (e.g. from another mod), event name -> variant list.
function mcl_mcsounds.register(event, variants)
	events[event] = variants
end

-- Plays a Minecraft sound event like Level.playSound(null, x, y, z, event,
-- source, volume, pitch). `spec` is a Luanti sound parameter table (pos,
-- object, to_player, exclude_player...). Like Minecraft's SoundEngine the
-- sound is heard up to max(volume, 1) * attenuation distance (16) blocks
-- and its gain is min(volume, 1); the variant's volume and pitch multiply.
-- Returns the sound handle (or nil) and the variant played.
function mcl_mcsounds.play(event, spec, volume, pitch, ephemeral)
	local variants = events[event]
	if not variants then
		core.log("warning", "[mcl_mcsounds] Unknown sound event " .. tostring(event))
		return nil
	end
	local v = pick(variants)
	volume = (volume or 1) * (v.volume or 1)
	pitch = math.min(2, math.max(0.5, (pitch or 1) * (v.pitch or 1)))
	local params = table.copy(spec or {})
	params.gain = math.min(1, volume) * (params.gain or 1)
	params.pitch = pitch
	if not params.to_player or params.pos or params.object then
		params.max_hear_distance = params.max_hear_distance
			or math.max(1, volume) * (v.attenuation_distance or 16)
	end
	return core.sound_play(v.name, params, ephemeral), v
end

-- A node sound definition (for `sounds` in node definitions) from the
-- Minecraft sound events of a SoundType "block.<type>" with its volume and
-- pitch (default 1). The engine plays node sounds by name and picks a random
-- file of the group "mcl_mc_block_<type>_<event>.N.ogg"; the variants'
-- volume and pitch are taken from the first one (they are equal for the
-- block sound types).
function mcl_mcsounds.node_sound(prefix, volume, pitch)
	volume = volume or 1
	pitch = pitch or 1
	local function s(event, vol, pit)
		local variants = events[prefix .. "." .. event]
		if not variants then
			return nil
		end
		return {
			name = "mcl_mc_" .. (prefix .. "_" .. event):gsub("%.", "_"),
			gain = math.min(1, vol * (variants[1].volume or 1)),
			pitch = pit * (variants[1].pitch or 1),
		}
	end
	return {
		-- Entity.playStepSound: volume * 0.15
		footstep = s("step", volume * 0.15, pitch),
		-- MultiPlayerGameMode.continueDestroyBlock: (volume + 1) / 8, pitch * 0.5
		dig = s("hit", (volume + 1) / 8, pitch * 0.5),
		-- LevelRenderer (break particles/sound): (volume + 1) / 2, pitch * 0.8
		dug = s("break", (volume + 1) / 2, pitch * 0.8),
		-- BlockItem.place: (volume + 1) / 2, pitch * 0.8
		place = s("place", (volume + 1) / 2, pitch * 0.8),
		-- LivingEntity.playBlockFallSound: volume * 0.5, pitch * 0.75
		fall = s("fall", volume * 0.5, pitch * 0.75),
	}
end
